// The fixtures are generated by ffmpeg when the tests run (a few KB each, nothing is committed): a burst at a known time, a silence
// of a known length, a tone at a known loudness (EBU TECH 3341: a 1 kHz sine at -23 dBFS in both channels reads -23.0 LUFS), a clip
// that clips, and clicks against a fake time map. Without ffmpeg on the PATH the tests skip, like the render tests.

func ffmpeg(t testing.TB) string {
	t.Helper()
	p, err := exec.LookPath("ffmpeg")
	if err != nil {
		if os.Getenv("CF_RENDER_REQUIRE_FFMPEG") != "" {
			t.Fatal("ffmpeg is not on PATH (CF_RENDER_REQUIRE_FFMPEG is set)")
		}
		t.Skip("ffmpeg is not on PATH")
	}
	return p
}

// fixtureDir is a directory the local sandbox may read and write.
func fixtureDir(t testing.TB) (dir string, runner media.Runner) {
	t.Helper()
	dir, err := filepath.EvalSymlinks(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	// The default work directory is a temporary one, so the system's temporary directory is a root as well.
	tmp, err := filepath.EvalSymlinks(os.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	return dir, &media.SandboxRunner{Provider: sandbox.NewLocal(sandbox.Policy{AllowedRoots: []string{dir, tmp}}), Limits: sandbox.DefaultLimits()}
}

// makeVideo writes a 30 fps video of dur seconds with the audio of the lavfi expression (empty: no audio track) and returns its path.
func makeVideo(t testing.TB, dir, name, audio string, dur float64, extra ...string) string {
	t.Helper()
	out := filepath.Join(dir, name)
	args := []string{"-hide_banner", "-loglevel", "error", "-y", "-f", "lavfi", "-i", "color=c=gray:s=160x96:r=30:d=" + num2(dur)}
	if audio != "" {
		args = append(args, "-f", "lavfi", "-i", audio)
	}
	args = append(args, "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p")
	if audio != "" {
		args = append(args, extra...)
		args = append(args, "-shortest")
	}
	args = append(args, out)
	cmd := exec.CommandContext(context.Background(), ffmpeg(t), args...) //nolint:gosec // test helper with fixed arguments
	if b, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("make %s: %v\n%s", name, err, b)
	}
	return out
}

func num2(f float64) string { return strconv.FormatFloat(f, 'f', -1, 64) }

func check(t testing.TB, runner media.Runner, path string, tm []render.TimeMapEntry, opts ...Option) Report {
	t.Helper()
	r, err := Check(context.Background(), runner, path, tm, opts...)
	if err != nil {
		t.Fatal(err)
	}
	return r
}

func find(r Report, id string) CheckItem {
	for _, c := range r.Checklist {
		if c.ID == id {
			return c
		}
	}
	return CheckItem{ID: "missing:" + id}
}

// An onset at a known time, and the silence around it.
func TestOnsetAndSilenceAtKnownTimes(t *testing.T) {
	dir, runner := fixtureDir(t)
	// A 200 ms tone with a 1 ms attack starts at exactly 1.000 s of a 3 s file, in digital silence.
	mp4 := makeVideo(t, dir, "burst.mp4", "aevalsrc='if(between(t,1,1.2),0.5*sin(2*PI*800*t)*min(1,(t-1)/0.001),0)':s=48000:d=3", 3, "-c:a", "aac", "-b:a", "192k")
	r := check(t, runner, mp4, nil)
	if !r.HasAudio || len(r.Onsets.List) != 1 {
		t.Fatalf("onsets %+v", r.Onsets.List)
	}
	if got := r.Onsets.List[0].TimeMs; got < 990 || got > 1012 {
		t.Errorf("the onset is at %d ms, want 1000 (+-12)", got)
	}
	if r.Onsets.List[0].RiseDB < 20 {
		t.Errorf("the rise is %.1f dB", r.Onsets.List[0].RiseDB)
	}
	// Silence: from the start to the burst, and from its end to the end of the file.
	if len(r.Silence.Gaps) != 2 {
		t.Fatalf("gaps %+v", r.Silence.Gaps)
	}
	if g := r.Silence.Gaps[0]; g.StartS > 0.05 || math.Abs(g.EndS-1.0) > 0.05 {
		t.Errorf("first gap %+v, want 0 to 1.0 s", g)
	}
	if g := r.Silence.Gaps[1]; math.Abs(g.StartS-1.2) > 0.06 || math.Abs(g.EndS-3.0) > 0.06 {
		t.Errorf("second gap %+v, want 1.2 to 3.0 s", g)
	}
	if math.Abs(r.Silence.EndS-1.8) > 0.08 {
		t.Errorf("silence at the end %.2f s, want 1.8", r.Silence.EndS)
	}
	// The hook: the first sound is the burst, not the start of the file.
	if math.Abs(r.Hook.FirstSoundS-1.0) > 0.02 {
		t.Errorf("first sound at %.3f s, want 1.0", r.Hook.FirstSoundS)
	}
	if c := find(r, "first_sound"); c.Status != StatusWarn {
		t.Errorf("a silent cold open of 1 s is a warning (past 1 s it fails): %+v", c)
	}
	if c := find(r, "dead_air_at_end"); c.Status != StatusFail {
		t.Errorf("1.8 s of silence at the end should fail: %+v", c)
	}
}

func TestSilentGapInTheMiddle(t *testing.T) {
	dir, runner := fixtureDir(t)
	mp4 := makeVideo(t, dir, "gap.mp4", "sine=frequency=440:sample_rate=48000:duration=4,volume='if(between(t,1.5,2.5),0,0.3)':eval=frame:precision=float", 4, "-c:a", "aac", "-b:a", "192k")
	r := check(t, runner, mp4, nil)
	if len(r.Silence.Gaps) != 1 {
		t.Fatalf("gaps %+v", r.Silence.Gaps)
	}
	g := r.Silence.Gaps[0]
	if math.Abs(g.StartS-1.5) > 0.06 || math.Abs(g.DurationS-1.0) > 0.1 || math.Abs(r.Silence.LongestS-1.0) > 0.1 {
		t.Errorf("gap %+v, longest %.2f: want 1.5 s start, 1.0 s long", g, r.Silence.LongestS)
	}
	if c := find(r, "silent_gap"); c.Status != StatusWarn {
		t.Errorf("a deliberate 1 s silence is a warning (a stop-down), not a failure: %+v", c)
	}
	if r.Silence.EndS > 0.1 {
		t.Errorf("silence at the end %.2f s, want none", r.Silence.EndS)
	}
}

// A tone at a known loudness: EBU TECH 3341 says a 1 kHz sine at -23 dBFS in both channels is -23.0 LUFS.
func TestLoudnessOfAKnownTone(t *testing.T) {
	dir, runner := fixtureDir(t)
	for _, level := range []float64{-23, -14, -9} {
		a := num2(math.Pow(10, level/20))
		src := "aevalsrc='" + a + "*sin(2*PI*1000*t)|" + a + "*sin(2*PI*1000*t)':s=48000:d=5"
		// PCM in a MOV: no codec to move the level.
		mov := makeVideo(t, dir, "tone.mov", src, 5, "-c:a", "pcm_s16le")
		r := check(t, runner, mov, nil)
		if math.Abs(r.Loudness.IntegratedLUFS-level) > 0.3 {
			t.Errorf("%.0f dB tone: %.2f LUFS integrated, want %.1f", level, r.Loudness.IntegratedLUFS, level)
		}
		if math.Abs(r.Loudness.TruePeakDBTP-level) > 0.6 {
			t.Errorf("%.0f dB tone: true peak %.2f dBTP, want about %.1f", level, r.Loudness.TruePeakDBTP, level)
		}
		if r.Loudness.RangeLU > 0.5 {
			t.Errorf("a steady tone has a loudness range of %.2f LU", r.Loudness.RangeLU)
		}
		// The momentary loudness reaches the level after its 400 ms window is full.
		if n := len(r.Loudness.Momentary); n < 45 || math.Abs(r.Loudness.Momentary[n-5].LUFS-level) > 0.4 {
			t.Errorf("momentary curve: %d points, late value %+v", n, r.Loudness.Momentary[max(n-5, 0)])
		}
		// Time to body: 0.4 s to fill the window (within 3 LU of the level needs most of it).
		if r.Hook.TimeToBodyS < 0.1 || r.Hook.TimeToBodyS > 0.6 {
			t.Errorf("time to body %.2f s", r.Hook.TimeToBodyS)
		}
		wantStatus := map[float64]string{-23: StatusWarn, -14: StatusPass, -9: StatusPass}[level]
		if level == -23 {
			wantStatus = StatusFail // -23 is 7 LU under the window: past the warning margin
		}
		if c := find(r, "loudness"); c.Status != wantStatus {
			t.Errorf("%.0f LUFS: loudness check %s, want %s (%+v)", level, c.Status, wantStatus, c)
		}
	}
}

func TestClippingDCAndBalance(t *testing.T) {
	dir, runner := fixtureDir(t)
	// A sine pushed into a hard clipper: samples at full scale.
	clipped := makeVideo(t, dir, "clip.mov", "aevalsrc='clip(4*sin(2*PI*300*t),-1,1)|clip(4*sin(2*PI*300*t),-1,1)':s=48000:d=3", 3, "-c:a", "pcm_s16le")
	r := check(t, runner, clipped, nil)
	if !r.Problems.Clipping || r.Problems.PeakDBFS < -0.1 {
		t.Errorf("a clipped file: %+v", r.Problems)
	}
	if c := find(r, "clipping"); c.Status != StatusFail {
		t.Errorf("clipping check: %+v", c)
	}
	// A clean tone is not clipped.
	clean := makeVideo(t, dir, "clean.mov", "aevalsrc='0.25*sin(2*PI*300*t)|0.25*sin(2*PI*300*t)':s=48000:d=3", 3, "-c:a", "pcm_s16le")
	if r := check(t, runner, clean, nil); r.Problems.Clipping || r.Problems.DC || r.Problems.Imbalance {
		t.Errorf("a clean tone has problems: %+v", r.Problems)
	}
	// DC: a tone riding on a 5 % offset.
	dc := makeVideo(t, dir, "dc.mov", "aevalsrc='0.05+0.2*sin(2*PI*300*t)|0.05+0.2*sin(2*PI*300*t)':s=48000:d=3", 3, "-c:a", "pcm_s16le")
	if r := check(t, runner, dc, nil); !r.Problems.DC || math.Abs(r.Problems.DCOffset-0.05) > 0.005 {
		t.Errorf("DC: %+v", r.Problems)
	}
	// One channel 12 dB under the other.
	lop := makeVideo(t, dir, "lop.mov", "aevalsrc='0.3*sin(2*PI*300*t)|0.075*sin(2*PI*300*t)':s=48000:d=3", 3, "-c:a", "pcm_s16le")
	r = check(t, runner, lop, nil)
	if !r.Problems.Imbalance || math.Abs(r.Problems.ImbalanceDB-12) > 1 {
		t.Errorf("imbalance: %+v", r.Problems)
	}
	if c := find(r, "channel_balance"); c.Status != StatusFail {
		t.Errorf("channel balance: %+v", c)
	}
}

// Sync against a fake time map: clicks at 1.0, 2.0 and 3.0 s; cuts at 1000 (exact), 2017 (half a frame late) and 3150 (150 ms off);
// effects planned at 1000 (heard) and 2500 (nothing there).
func TestSyncAgainstTheTimeMap(t *testing.T) {
	dir, runner := fixtureDir(t)
	src := "aevalsrc='0.6*sin(2*PI*1500*t)*(between(t,1,1.03)+between(t,2,2.03)+between(t,3,3.03))*min(1,mod(t,1)/0.001)':s=48000:d=4"
	mp4 := makeVideo(t, dir, "clicks.mp4", src, 4, "-c:a", "aac", "-b:a", "192k")
	in := func(v int64) *int64 { return &v }
	sp := 1.0
	tm := []render.TimeMapEntry{
		{OutStartMs: 0, OutEndMs: 1000, ItemID: "c1", SourceInMs: in(0), Speed: &sp},
		{OutStartMs: 1000, OutEndMs: 2017, ItemID: "c2", SourceInMs: in(0), Speed: &sp},
		{OutStartMs: 2017, OutEndMs: 3150, ItemID: "c3", SourceInMs: in(0), Speed: &sp},
		{OutStartMs: 3150, OutEndMs: 4000, ItemID: "c4", SourceInMs: in(0), Speed: &sp},
		{OutStartMs: 500, OutEndMs: 900, ItemID: "t1"}, // a text item: not a cut
	}
	r := check(t, runner, mp4, tm, WithFPS(30), WithSFX([]PlannedSFX{{ID: "s1", Sfx: "click", AtMs: 1000}, {ID: "s2", Sfx: "whoosh", AtMs: 2500}}))
	if len(r.Onsets.List) != 3 {
		t.Fatalf("onsets %+v", r.Onsets.List)
	}
	for i, want := range []int64{1000, 2000, 3000} {
		if got := r.Onsets.List[i].TimeMs; got < want-12 || got > want+12 {
			t.Errorf("onset %d at %d ms, want %d (+-12)", i, got, want)
		}
	}
	if len(r.Sync.Cuts) != 3 || r.Sync.Cuts[0].AtMs != 1000 || r.Sync.Cuts[1].AtMs != 2017 || r.Sync.Cuts[2].AtMs != 3150 {
		t.Fatalf("cuts %+v", r.Sync.Cuts)
	}
	if d := r.Sync.Cuts[0].DeltaMs; d < -12 || d > 12 {
		t.Errorf("cut 1: delta %d ms", d)
	}
	if d := r.Sync.Cuts[1].DeltaMs; d < -29 || d > -5 {
		t.Errorf("cut 2: delta %d ms, want about -17", d)
	}
	if d := r.Sync.Cuts[2].DeltaMs; d < -165 || d > -135 {
		t.Errorf("cut 3: delta %d ms, want about -150", d)
	}
	if got := r.Sync.CutsWithinFrameShare; math.Abs(got-2.0/3) > 0.01 {
		t.Errorf("cuts within a frame: %.3f, want 2/3", got)
	}
	if got := r.Sync.CutsWithin100msShare; math.Abs(got-2.0/3) > 0.01 {
		t.Errorf("cuts within 100 ms: %.3f, want 2/3", got)
	}
	// The effects: one heard on its frame, one not heard.
	if r.Sync.SFXPlanned != 2 || r.Sync.SFXFound != 1 || math.Abs(r.Sync.SFXWithinFrameShare-0.5) > 0.01 {
		t.Errorf("effects: %+v", r.Sync)
	}
	if !r.Sync.SFX[0].WithinFrame || r.Sync.SFX[1].OnsetMs != -1 {
		t.Errorf("effects: %+v", r.Sync.SFX)
	}
	if got := r.Density.SFXPer10s; math.Abs(got-5) > 0.01 {
		t.Errorf("effects per 10 s: %.2f, want 5", got)
	}
	if c := find(r, "sfx_density"); c.Status != StatusWarn {
		t.Errorf("5 effects per 10 s: %+v", c)
	}
	// Chance: shifted by 300..900 ms the cuts have no onset within 100 ms (the clicks are 1 s apart: some shifts land on one).
	if r.Sync.ChanceWithin100msShare < 0 || r.Sync.ChanceWithin100msShare > 1 {
		t.Errorf("chance %.3f", r.Sync.ChanceWithin100msShare)
	}
}

func TestNoAudioAndSilentAudio(t *testing.T) {
	dir, runner := fixtureDir(t)
	mute := makeVideo(t, dir, "mute.mp4", "", 2)
	r := check(t, runner, mute, nil)
	if r.HasAudio || find(r, "has_audio").Status != StatusFail || !strings.Contains(r.Summary, "no sound track") {
		t.Errorf("a video without audio: %+v / %s", r.Checklist, r.Summary)
	}
	if len(r.Sheet) == 0 {
		t.Error("no sheet for a video without audio")
	}
	// A silent track, like a preview of a timeline with every source muted.
	silent := makeVideo(t, dir, "silent.mp4", "anullsrc=r=48000:cl=stereo:d=3", 3, "-c:a", "aac", "-b:a", "128k")
	r = check(t, runner, silent, nil)
	if !r.HasAudio || r.Loudness.IntegratedLUFS > -69 || !strings.Contains(r.Summary, "digital silence") {
		t.Errorf("a silent track: %.1f LUFS / %s", r.Loudness.IntegratedLUFS, r.Summary)
	}
	if c := find(r, "loudness"); c.Status != StatusFail {
		t.Errorf("loudness of silence: %+v", c)
	}
	if r.Hook.FirstSoundS != -1 || r.Hook.TimeToBodyS != -1 {
		t.Errorf("hook of silence: %+v", r.Hook)
	}
	// The report is plain JSON: no infinities, no NaN.
	if _, err := json.Marshal(r); err != nil {
		t.Errorf("a silent report does not marshal: %v", err)
	}
}

// The sheet is a PNG of the fixed size, with the markers in the places the time map and the plan put them.
func TestSheetDrawsTheMarkersOnTheTimeAxis(t *testing.T) {
	dir, runner := fixtureDir(t)
	mp4 := makeVideo(t, dir, "tone.mp4", "aevalsrc='0.2*sin(2*PI*440*t)|0.2*sin(2*PI*440*t)':s=48000:d=4", 4, "-c:a", "aac", "-b:a", "128k")
	in := func(v int64) *int64 { return &v }
	sp := 1.0
	tm := []render.TimeMapEntry{
		{OutStartMs: 0, OutEndMs: 2000, ItemID: "c1", SourceInMs: in(0), Speed: &sp},
		{OutStartMs: 2000, OutEndMs: 4000, ItemID: "c2", SourceInMs: in(0), Speed: &sp},
	}
	r := check(t, runner, mp4, tm, WithFPS(30), WithSFX([]PlannedSFX{{ID: "s1", Sfx: "impact", AtMs: 1000}}))
	img, err := png.Decode(bytes.NewReader(r.Sheet))
	if err != nil {
		t.Fatal(err)
	}
	w, h := SheetSize()
	if b := img.Bounds(); b.Dx() != w || b.Dy() != h {
		t.Fatalf("sheet is %dx%d, want %dx%d", b.Dx(), b.Dy(), w, h)
	}
	x := func(ms float64) int { return marginL + int(math.Round(ms/1000/r.DurationS*float64(w-marginL-marginR))) }
	probe := func(px, py int) [3]uint8 {
		r, g, b, _ := img.At(px, py).RGBA()
		return [3]uint8{uint8(r >> 8), uint8(g >> 8), uint8(b >> 8)}
	}
	laneY := legendH + waveH + panelGap + loudH + panelGap + 20
	if got := probe(x(2000), laneY); got != [3]uint8{245, 245, 245} {
		t.Errorf("no cut marker at 2.0 s: %v", got)
	}
	if got := probe(x(1000), laneY); got != [3]uint8{255, 70, 200} {
		t.Errorf("no effect marker at 1.0 s: %v", got)
	}
	if got := probe(x(1500), laneY); got == [3]uint8{245, 245, 245} || got == [3]uint8{255, 70, 200} {
		t.Errorf("a marker where there is none: %v", got)
	}
	// The tile markers sit at the contact sheet's frame times: 100 ms after the start and after the cut.
	axisY := legendH + waveH + panelGap + loudH + panelGap + laneH + axisH - 1
	if got := probe(x(2100), axisY); got != [3]uint8{60, 200, 255} {
		t.Errorf("no tile marker at 2.1 s: %v", got)
	}
	if len(r.Sheet) > 80<<10 {
		t.Errorf("the sheet is %d bytes", len(r.Sheet))
	}
}

func TestRejectsAFileThatIsNotMedia(t *testing.T) {
	dir, runner := fixtureDir(t)
	bad := filepath.Join(dir, "we ird;name'.mp4")
	if err := os.WriteFile(bad, bytes.Repeat([]byte("not a video "), 100), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := Check(context.Background(), runner, bad, nil); err == nil {
		t.Error("garbage was accepted")
	}
	if _, err := Check(context.Background(), runner, filepath.Join(dir, "missing.mp4"), nil); err == nil {
		t.Error("a missing file was accepted")
	}
	ffmpeg(t)
	// A path with spaces and quotes is fine for a real file: it is a mount, never part of the arguments.
	good := makeVideo(t, dir, "we ird;name'.mp4", "sine=frequency=440:duration=1", 1, "-c:a", "aac")
	if r := check(t, runner, good, nil); !r.HasAudio {
		t.Error("a file with an odd name was not read")
	}
}

// A mono file is read at its own level: the mono dump is not halved the way a pan of a missing second channel would be (a quiet
// sound just above the first-sound threshold would be lost), and a log without its summary is an error, not silence.
func TestAMonoFileIsReadAtItsOwnLevel(t *testing.T) {
	dir, runner := fixtureDir(t)
	// A 1 kHz mono tone of 0.005 (-46 dBFS peak, -49 dBFS RMS) from 0.3 s, just above the -50 dBFS first-sound threshold: at its own
	// level it is heard, halved (-55 dBFS) it would not be.
	mp4 := makeVideo(t, dir, "mono.mp4", "aevalsrc='if(gte(t,0.3),0.005*sin(2*PI*1000*t),0)':s=48000:d=2:c=mono", 2, "-c:a", "aac", "-b:a", "192k")
	r := check(t, runner, mp4, nil)
	if math.Abs(r.Hook.FirstSoundS-0.3) > 0.02 {
		t.Errorf("first sound at %.3f s, want 0.3: the mono dump is at the wrong level", r.Hook.FirstSoundS)
	}
	if len(r.Problems.ChannelRMSDB) != 1 {
		t.Errorf("channels %v", r.Problems.ChannelRMSDB)
	}
	// A channel balance check needs two channels.
	if find(r, "channel_balance").ID != "missing:channel_balance" {
		t.Error("a mono file has a channel balance check")
	}
}

// An effect on the very first frame is the loudest thing in the file from its first sample: it has no quiet before it, and it is
// still heard. Effects planned after the end of the file are not counted at all.
func TestAnEffectOnTheFirstFrameIsHeard(t *testing.T) {
	dir, runner := fixtureDir(t)
	mp4 := makeVideo(t, dir, "first.mp4", "aevalsrc='0.6*sin(2*PI*900*t)*exp(-t/0.08)':s=48000:d=2", 2, "-c:a", "aac", "-b:a", "192k")
	r := check(t, runner, mp4, nil, WithFPS(30), WithSFX([]PlannedSFX{{ID: "s1", Sfx: "impact", AtMs: 0}, {ID: "s2", Sfx: "whoosh", AtMs: 5000}}))
	if r.Sync.SFXPlanned != 1 || r.Sync.SFXFound != 1 || !r.Sync.SFX[0].WithinFrame {
		t.Errorf("effects: %+v", r.Sync)
	}
	if r.Density.SFXCount != 1 || math.Abs(r.Density.SFXPer10s-5) > 0.01 {
		t.Errorf("density counts an effect that is past the end: %+v", r.Density)
	}
	if c := find(r, "sfx_sync"); c.Status != StatusPass {
		t.Errorf("sfx sync: %+v", c)
	}
}
